alter table public.hewers_stock_movements drop constraint hewers_stock_movements_movement_type_check, drop constraint hewers_stock_movements_quantity_check; alter table public.hewers_stock_movements add constraint hewers_stock_movements_movement_type_check check (movement_type in ('Opening','Delivery','Issue','Return','Damage','Loss')), add constraint hewers_stock_movements_quantity_check check (quantity>0 or (movement_type='Opening' and quantity=0));
